function lock(which){lastFocus=document.activeElement;scrollLock=scrollY;document.body.style.overflow='hidden';$('#main').inert=true;$('#header').inert=true;$('#quick-open').inert=true;$$('main video').forEach(v=>v.pause());overlay=which;const el=document.getElementById(which);el.hidden=false;requestAnimationFrame(()=>el.classList.add('open'));el.querySelector('.close')?.focus();}
function unlock(which,immediate=false){if(closing.has(which))return closing.get(which);const el=document.getElementById(which);if(!el||el.hidden)return Promise.resolve();el.classList.remove('open');el.classList.add('closing');const promise=new Promise(resolve=>setTimeout(()=>{el.querySelectorAll('video').forEach(v=>v.pause());el.hidden=true;el.classList.remove('closing');document.body.style.overflow='';$('#main').inert=false;$('#header').inert=false;$('#quick-open').inert=false;overlay=null;setupMediaResume();if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true});if(which==='menu'){symbols=[];$('#menu-open').setAttribute('aria-expanded','false')}closing.delete(which);resolve()},immediate||reduced?0:which==='menu'?580:300));closing.set(which,promise);return promise;}
function menuOpen(){if(overlay||transitioning)return;$('#menu-links').innerHTML=[['','Home'],['projects',L('Progetti','Work')],['services',L('Servizi','Services')],['studio','Studio'],['contact',L('Contatti','Contact')]].map((n,i)=>`<a href="#/${n[0]}" style="--i:${i}">${n[1]}</a>`).join('');$('#menu-date').textContent=new Date().toLocaleDateString(lang==='it'?'it-CH':'en-GB');lock('menu');$('#menu-open').setAttribute('aria-expanded','true');const navLinks=$$('#menu-links a');navLinks.forEach(a=>{a.addEventListener('pointerenter',()=>underline(a));a.addEventListener('focus',()=>underline(a))});setTimeout(()=>underline(navLinks.find(a=>a.getAttribute('href')==='#/'+(route==='home'?'':route))||navLinks[0]),150);const colors=['#afa7ef','#ecacae','#a8d393','#d8b164','#ef997e','#ccbee7'];symbols=Array.from({length:16},(_,i)=>({x:(i*197%Math.max(1,innerWidth-100)),y:-180-i*80,vx:Math.sin(i*2)*.12,vy:0,size:85+(i*31%90),angle:i*47,spin:Math.cos(i)*.07,settled:false,delay:i*30}));$('#falling-symbols').innerHTML=symbols.map((s,i)=>`<i style="width:${s.size}px;height:${s.size}px;background:${colors[i%6]}"></i>`).join('');symbolTime=0;}
function underline(a){if(!a)return;const r=$('#menu-links').getBoundingClientRect();const u=$('#menu-underline');u.style.width=a.offsetWidth+'px';u.style.left=(r.left+a.offsetLeft)+'px';u.style.top=(r.top+a.offsetTop+a.offsetHeight-4)+'px'}
function animateSymbols(dt,h,w){symbolTime+=dt;const els=[...$('#falling-symbols').children];symbols.forEach((s,i)=>{if(symbolTime<s.delay+300)return;const floor=h-s.size*.8-(i%3)*10;if(!reduced){s.vy+=dt*.00155;s.x+=s.vx*dt;s.y+=s.vy*dt;s.angle+=s.spin*dt;if(s.y>floor){s.y=floor;s.vy*=-.32;s.vx*=.85;s.spin*=.5;if(Math.abs(s.vy)<.06){s.vy=0;s.spin=0;s.settled=true}}if(s.x<0||s.x>w-s.size){s.vx*=-.5;s.x=M.clamp(s.x,0,w-s.size)}}else s.y=floor;els[i].style.transform=`translate(${s.x}px,${s.y}px) rotate(${s.angle}deg)`})}
